    "indigenous": "Baba wa k'ambo si baba.",
    "literalTranslation": "A step-father is not a father.",
    "meaning": "A step-father is not a father.",
    "theme": "family",
    "sourceCitation": "Rev. W. E. Taylor, M.A. (1891) 'African Aphorisms; or, Saws from Swahili-Land' (SPCK, London), Swahili Proverb #42"
