    "languageId": "swahili",
    "languageName": "Kiswahili",
    "indigenous": "Fadhili za p'unda ni mashuzi: na msinathari ni ng'ombe.",
    "literalTranslation": "The favours of a donkey are,—wind: and the witless person is (but) an ox.",
    "meaning": "The favours of a donkey are,—wind: and the witless person is (but) an ox.",
    "theme": "family",
    "sourceCitation": "Rev. W. E. Taylor, M.A. (1891) 'African Aphorisms; or, Saws from Swahili-Land' (SPCK, London), Swahili Proverb #65"
