    "languageId": "swahili",
    "languageName": "Kiswahili",
    "indigenous": "Kafiri akufaae, si Isilamu asiyekufaa.",
    "literalTranslation": "An unbeliever that is of use to you is better than a Moslem that is of no use to you.",
