    "languageId": "swahili",
    "languageName": "Kiswahili",
    "indigenous": "Kijana akililia kisu, mpe.",
    "literalTranslation": "If a child cry for a knife, give it to him.",
    "meaning": "He will learn better what a knife is from a few moments' experience than you could ever teach him by mere warnings.",
    "theme": "family",
    "sourceCitation": "Rev. W. E. Taylor, M.A. (1891) 'African Aphorisms; or, Saws from Swahili-Land' (SPCK, London), Swahili Proverb #143"
