    "indigenous": "Kijana ukimnyang'anya kisu mpe kijiti.",
    "literalTranslation": "If you take away a knife from a child, give him a stick (instead).",
    "meaning": "He will be equally pleased, and it can do him no harm: make up for a wise deprivation by a wise indulgence.",
    "theme": "family",
    "sourceCitation": "Rev. W. E. Taylor, M.A. (1891) 'African Aphorisms; or, Saws from Swahili-Land' (SPCK, London), Swahili Proverb #144"
