    "languageId": "swahili",
    "languageName": "Kiswahili",
    "indigenous": "Mt'u neno ajapokuwa halipendi, lakini akishurutizwa ni wat'u wangi hufuata: si vyema kukataa, ni heri kutenda.",
    "literalTranslation": "When a man is constrained by many persons, although he may not like the matter, still he complies (lit. follows): it is wrong to refuse, it is best to do it.",
