    "meaning": "\"A whited sepulchre.\" St. Matt. xxiii. 27. Hypocrisy, see § 469. Maana: ni mt'u ambae ni mzuri na tabia yakwe ni mbaya. The meaning is, a man that is handsome but has an evil disposition.",
