    "languageName": "Kiswahili",
    "indigenous": "Wa kuume hauk'ati wa kushoto.",
    "literalTranslation": "The right (hand) cutteth not the left.",
    "meaning": "The right (hand) cutteth not the left.",
    "theme": "wisdom",
