    "languageId": "swahili",
    "languageName": "Swahili (Kiswahili)",
    "indigenous": "Hujui kula na kipofu, usingemgusa vyanda.",
    "literalTranslation": "You do not know (how) to eat (out of the same dish) with a blind man, (or) you would not touch his fingers.",
    "meaning": "If his fingers (vyanda, pl. of chanda 'finger' in Kimvita/Northern Swahili) are disturbed, they will wander from his particular portion of the common mess into that of the others. Do not arouse suspicion in someone who is already at a disadvantage.",
