    "literalTranslation": "That which devours thee is in thy clothes.",
    "meaning": "Compare Micah vii. 6 ('A man's enemies are the men of his own house') and § 502 ('T'ek'e la k'uku mwenyewe halimuumizi'). Ki is the Class 7 copula ('it is'—scil. kitu kikulacho, referring to a louse or hidden betrayer within one's own household or inner circle).",
