    "languageId": "swahili",
    "languageName": "Swahili (Kiswahili)",
    "indigenous": "Kulla muata samboye hwenda ali mwanamaji.",
    "literalTranslation": "Every one leaving his (own) vessel goes as a common sailor.",
    "meaning": "Samboye = sambo yakwe; sambo is an archaic Kingozi/poetic word for chombo ('vessel/dhow'). Ali = akawa ('being'). A captain or owner who abandons his own craft must serve as a common seaman (mwanamaji / baharia) on someone else's.",
