    "indigenous": "(1) Mpiga la kuanza hunyamaziwa; Mpiga la pili huitwa akambiwa; Mpiga la tatu huonguliwa • (2) Kiendacho kwa mganga hakirudi • (3) Kiungu kia mwovu hakivunjiki (Momb. Nyungu ya mwovu haivundiki) • (4) Wema hauozi • (5) Jambo usilolijua ni usiku wa kiza • (6) Kukopa harusi, kulipa matanga • (7) Killa mtoto na koja lake • (8) Shimo ulilolichimba utatumbukia mwenyewe • (9) Mpanda farasi wawili hupasuka msamba • (10) Mwenye kisu kikali ndiye alae nyama • (11) Kuku mgeni hakosi kamba mguuni • (12) Ulimi hauna mfupa • (13) Kuagiza kufikile • (14) Kuambiana kuko kusikilizana hapana • (15) Mzoea kutwaa, kumpa ni matanga • (16) Kufa kwa wangi ni harusi • (17) Mwenye macho haambiwi tazama • (18) Akili nyingi huondoa maarifa • (19) Samaki mmoja akioza, wote wameoza • (20) Fuata nyuki ule asali.",
    "literalTranslation": "(1) The striker of the first blow is ignored; the striker of the second is called and warned; the striker of the third is punished • (2) What goes to the medicine-man does not return • (3) The wicked man's cooking-pot does not break • (4) Goodness does not rot • (5) A matter you do not know is a dark night • (6) Borrowing is a wedding, paying back is mourning • (7) Every child has its own neck-ornament • (8) The pit you dug you will fall into yourself • (9) He who rides two horses splits his perineum • (10) He who has a sharp knife is the one who eats meat • (11) A strange fowl never lacks a string on its leg • (12) The tongue has no bone • (13) Ordering has arrived • (14) Telling each other exists, listening to each other does not • (15) To one used to taking, giving is mourning • (16) The death of many is a wedding • (17) One who has eyes is not told 'look' • (18) Too much cleverness drives away practical wisdom • (19) If one fish rots, all have rotted • (20) Follow the bee that you may eat honey.",
    "meaning": "Verbatim Ki-Jizirat (Pemba) and Ki-Mvita (Mombasa) aphorisms (Mafumbo) Nos. 1–20 with Wa-Swahili explanations in Mervyn W. H. Beech's 'Aids to the Study of Ki-Swahili' (1918, Study III, pp. 117–120).",
    "englishEquivalent": "Borrowing is pleasant, repaying is hard; one rotten apple spoils the barrel; too many cooks spoil the broth.",
