    "languageId": "swahili",
    "languageName": "Kiswahili (Ki-Jizirat & Ki-Mvita — Beech 1918)",
    "indigenous": "(21) Mwana wa muhunzi asiposana huvukuta • (22) Usitukane wakunga na uzazi ungalipo • (23) Zimwi likujualo halikuli likakwisha • (24) Maji yakimwagika hayazoleki • (25) Kenda karibu na kumi • (26) Lisemwalo lipo, ikiwa halipo laja • (27) Paka akiondoka panya hutawala • (28) Mwenda pole hajikwai • (29) Haba na haba hujaza kibaba • (30) Bandu bandu humaliza gogo • (31) Kila ndege huruka kwa bawa lake • (32) Maji hufuata mkondo • (33) Sikio la kufa halisikii dawa • (34) Damu nzito kuliko maji • (35) Hiyari ya mtu ni mwenyewe (Momb. Hiyari hushinda utumwa) • (36) Mchimba kisima huingia mwenyewe • (37) Kiombo kia kuzama hakina usukani (Momb. Chombo cha kuzama hakina usukani) • (38) Mkono mtupu haulambwi • (39) Mwenye shibe hamjui mwenye njaa • (40) Fimbo ya mbali haiui nyoka • (41) Jungu kuu halikosi ukoko • (42) Mti mkuu ukigwa wana wa ndege huyumba • (43) Kwa mwoga huenda kicheko, kwa shujaa huenda kilio • (44) Subira huvuta heri • (45) Haraka haraka haina baraka.",
    "literalTranslation": "(21) If the blacksmith's son does not forge, he blows the bellows • (22) Do not insult the midwives while childbearing still continues • (23) The ogre that knows you does not eat you up completely • (24) Water once spilled cannot be gathered up • (25) Nine is near to ten • (26) What is spoken of is there; if it is not there, it is coming • (27) When the cat leaves, the rats rule • (28) He who walks gently does not stub his toe • (29) Little by little fills the kibaba measure • (30) Chip by chip finishes the log • (31) Every bird flies with its own wing • (32) Water follows the current • (33) A dying ear does not hear medicine • (34) Blood is heavier than water • (35) A man's free choice belongs to himself (Freewill overcomes slavery) • (36) He who digs a well enters it himself • (37) A sinking vessel has no rudder • (38) An empty hand is not licked • (39) A full man does not know a hungry man • (40) A distant stick does not kill a snake • (41) A great cooking-pot never lacks crust • (42) When the great tree falls, the young birds reel • (43) To the coward's house goes laughter, to the hero's goes weeping • (44) Patience draws blessing • (45) Hurry, hurry has no blessing.",
    "meaning": "Verbatim Ki-Jizirat (Pemba) and Ki-Mvita (Mombasa) aphorisms (Mafumbo) Nos. 21–45 with Wa-Swahili explanations in Mervyn W. H. Beech's 'Aids to the Study of Ki-Swahili' (1918, Study III, pp. 120–123).",
    "englishEquivalent": "Like father, like son; when the cat's away, the mice will play; discretion is the better part of valour.",
    "theme": "courage",
    "sourceCitation": "Mervyn W. H. Beech, Aids to the Study of Ki-Swahili (London: Kegan Paul, 1918, Study III, Mafumbo Nos. 21–45, pp. 120–123)"
